export function shippingCost(weightGrams: number): number {
  const extraKg = Math.max(weightGrams - 1000, 0) / 1000;
  const started = Math.ceil(extraKg);
  return FIRST_KG_CENTS + EXTRA_KG_CENTS * started;
}

